SELECT SUM(CASE WHEN m.label = '+' AND a.element = 'h' THEN 1 ELSE 0 END) * 100.0 / COUNT(m.molecule_id) AS percentage
FROM molecule m
JOIN atom a ON m.molecule_id = a.molecule_id;

SELECT
  (SELECT COUNT(*) FROM posts p JOIN users u ON p.OwnerUserId = u.Id WHERE u.CreationDate = (SELECT MAX(CreationDate) FROM users)) AS post_count,
  (SELECT COUNT(*) FROM comments c JOIN users u ON c.UserId = u.Id WHERE u.CreationDate = (SELECT MAX(CreationDate) FROM users)) AS comment_count;

SELECT
  (SELECT COUNT(*) FROM comments c JOIN posts p ON c.PostId = p.Id WHERE p.Title = 'Clustering 1D data') AS num_comments,
  (SELECT COUNT(*) FROM posts a JOIN posts p ON a.ParentId = p.Id WHERE p.Title = 'Clustering 1D data' AND a.PostTypeId = 2) AS num_answers;

