def determine_bond_type(element='c'):
    """Determine the bond types formed by an element in a compound."""
    bond_map = {
        'c': ['-', '=', '#'],   # Carbon: single, double, and triple bonds
        'h': ['-'],             # Hydrogen: single bonds only
        'o': ['-', '='],        # Oxygen: single and double bonds
        'n': ['-', '=', '#'],   # Nitrogen: single, double, and triple bonds
    }
    return bond_map.get(element, [])

print(determine_bond_type('c'))  # Output: ['-', '=', '#']

